using System;using System.IO;using System.Linq;using System.Text;using Frociart;
internal static class CodeTemplateStoreTests {
 static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}static void Reject(Action action,string why){try{action();}catch(Exception e){if(e is IOException||e is ArgumentException){checks++;return;}throw;}throw new Exception("Expected rejection: "+why);}
 static FlowCodeTemplate T(string name="Python personale"){return FlowCodeTemplate.Create(name,"python","py","Python 3","# {{ project.title | literal }}\n{{ source }}");}
 static int Main(string[] args){try{string folder=Path.Combine(args[0],"store-tests",Guid.NewGuid().ToString("N"));var store=new FlowTemplateStore(folder);Check(store.Entries().Count==0&&!Directory.Exists(folder),"Read of absent library does not create storage");string emptyId=FlowTemplateStore.NewId();Directory.CreateDirectory(Path.Combine(folder,emptyId));for(int e=0;e<35;e++)Directory.CreateDirectory(Path.Combine(folder,FlowTemplateStore.NewId()));Check(store.Entries().Count==0,"Empty directories never appear as phantom models or consume capacity");string id=FlowTemplateStore.NewId();string draft="bozza non valida {{";store.SaveDraft(id,draft);var entry=store.Load(id);Check(entry.Raw==null&&entry.Draft==draft&&store.Entries().Count==1,"Unsaved draft survives reopening");entry=store.Save(id,T().Text,null);Check(entry.Definition.Text==T().Text&&entry.Fingerprint!=null&&entry.Draft==draft,"Real save preserves separate unfinished draft");Check(!store.ClearDraft(id,"obsolete")&&store.Load(id).Draft==draft,"Stale completion cannot discard newer draft");Check(store.ClearDraft(id,draft)&&store.Load(id).Draft==null,"Explicit matching draft clear");
  string fingerprint=entry.Fingerprint;Reject(()=>store.Save(id,T().Text.Replace("{{ source }}","{% if true %}"),fingerprint),"Invalid template never replaces saved one");Check(store.Load(id).Fingerprint==fingerprint,"Invalid save preserves original bytes");var other=new FlowTemplateStore(folder);entry=other.Save(id,T("Aggiornato").Text,fingerprint);Reject(()=>store.Save(id,T().Text,fingerprint),"Revision guard across store instances");Check(store.Load(id).Fingerprint==entry.Fingerprint,"Conflicting save preserves newer template");
  string second=FlowTemplateStore.NewId();Reject(()=>store.Save(second,T("Aggiornato").Text,null),"Duplicate names rejected");Check(!Directory.Exists(Path.Combine(folder,second)),"Rejected new model creates no empty entry directory");
  using(var busy=new FileStream(Path.Combine(folder,".lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None))Reject(()=>store.SaveDraft(id,"new draft"),"Actual exclusive lock prevents a second writer");Check(store.Load(id).Draft==null,"Busy archive retains prior draft state");
  store.SaveDraft(id,"editing");store.Archive(id,entry.Fingerprint);Check(store.Entries().Count==0&&store.Entries(true).Single().Draft=="editing","Atomic archive retains main and draft");store.Restore(id);Check(store.Load(id).Fingerprint==entry.Fingerprint&&store.Load(id).Draft=="editing"&&store.Entries(true).Count==0,"Restore preserves exact main revision and draft");
  string extra=Path.Combine(folder,id,"outside.txt");File.WriteAllText(extra,"OWNED FIXTURE");Reject(()=>store.Archive(id,entry.Fingerprint),"Unknown files are never moved or deleted");Check(File.ReadAllText(extra)=="OWNED FIXTURE"&&store.Entries().Count==1,"Unknown-file failure preserves entire active entry");File.Delete(extra);
  string export=Path.Combine(folder,"external.frotemplate");FlowTemplateStore.Export(export,entry.Definition);Check(FlowCodeTemplate.Parse(FlowTemplateStore.ReadImport(export)).Text==entry.Definition.Text,"Actual canonical UTF8 export and import");File.WriteAllText(export,"ORIGINAL");FlowTemplateStore.Export(export,T("Export nuovo"));Check(File.ReadAllText(export)==T("Export nuovo").Text,"Confirmed external replacement writes actual new template");
  File.WriteAllBytes(export,new byte[]{255,0,255});Reject(()=>FlowTemplateStore.ReadImport(export),"Malformed UTF8 import rejected");Reject(()=>store.SaveDraft("../outside","payload"),"Traversal identifier rejected");Reject(()=>store.SaveDraft(id,"\ud800"),"Unpaired Unicode draft rejected");Check(store.Load(id).Draft=="editing","Invalid Unicode never overwrites existing draft");
  store.Archive(id,entry.Fingerprint);store.DeleteArchived(id);Check(store.Entries().Count==0&&store.Entries(true).Count==0&&!Directory.Exists(Path.Combine(folder,"archive",id)),"Explicit permanent delete only removes archived entry");
  for(int i=0;i<FlowTemplateStore.MaxEntries;i++)store.Save(FlowTemplateStore.NewId(),T("Modello "+i).Text,null);Reject(()=>store.SaveDraft(FlowTemplateStore.NewId(),"new"),"Library entry count bound");Reject(()=>store.SaveDraft(emptyId,"new"),"Existing empty directory cannot bypass model count limit");Check(store.Entries().Count==FlowTemplateStore.MaxEntries,"Entry limit leaves every previous model intact");
  string corrupt=store.Entries()[0].Id,main=Path.Combine(folder,corrupt,"definition.frotemplate");File.WriteAllBytes(main,new byte[FlowCodeTemplate.MaxBytes+1]);var broken=store.Load(corrupt);Check(broken.Problem!=null&&broken.Fingerprint==null,"Oversized stored file becomes recoverable problem entry");Reject(()=>store.Save(corrupt,T("Corretto").Text,null),"Unreadable saved file cannot be mistaken for absent entry");Check(new FileInfo(main).Length==FlowCodeTemplate.MaxBytes+1,"Unrecoverable read never overwrites original data");
  Check(!Directory.EnumerateFiles(folder,".pending-*",SearchOption.AllDirectories).Any(),"Atomic writes leave no pending temporary files");var form=new FlowTemplateDraft("","python","","incompleto 🐢","{% if true %}\n0\n\n🐢",false);var restored=FlowTemplateDraft.Decode(form.Encode());Check(restored.Name==form.Name&&restored.Body==form.Body&&restored.Instructions==form.Instructions&&!restored.CaseSensitive,"Unfinished form codec preserves Unicode, empty fields and invalid syntax");Reject(()=>FlowTemplateDraft.Decode(form.Encode()+"trailing"),"Trailing draft garbage");Reject(()=>FlowTemplateDraft.Decode("FrociartTemplateDraft1\n999999\nshort"),"Truncated draft");File.WriteAllText(Path.Combine(args[0],"draft-example.txt"),form.Encode(),new UTF8Encoding(false));Console.WriteLine("TEMPLATE_STORE_PC PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
